const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Beira and Manga, Mozambique (approximate points), unioned buffers to cover both
    const beiraPt = ee.Geometry.Point([34.845, -19.823]);
    const mangaPt = ee.Geometry.Point([34.870, -19.820]);
    const geom = beiraPt.buffer(5000).union(mangaPt.buffer(5000)); // ~5 km buffers

    const dateA = '2019-03-09';
    const dateB = '2019-03-24';
    const datasetId = 'NOAA/VIIRS/001/VNP46A1'; // NASA Black Marble daily VIIRS

    // 2. Data Acquisition & Band detection (robust)
    let baseCol = ee.ImageCollection(datasetId)
      .filterBounds(geom)
      .filterDate('2019-02-15', '2019-04-15');
    let baseSize = await baseCol.size().getInfo();
    if (baseSize === 0) {
      // Expand even more just in case
      baseCol = ee.ImageCollection(datasetId)
        .filterBounds(geom)
        .filterDate('2018-12-01', '2019-06-01');
      baseSize = await baseCol.size().getInfo();
      if (baseSize === 0) {
        console.log(`Collection (${datasetId}) has 0 images for the wider period.`);
        console.log('C1');
        return;
      }
    }
    const firstImg = ee.Image(baseCol.first());
    const bands = await firstImg.bandNames().getInfo();
    const candidateBands = [
      'DNB_BRDF-Corrected_NTL',
      'DNB_BRDF_Corrected_NTL',
      'Gap_Filled_DNB_BRDF-Corrected_NTL',
      'Gap_Filled_DNB_BRDF_Corrected_NTL',
      'Radiance'
    ];
    let targetBand = candidateBands.find(b => bands.includes(b));
    if (!targetBand) {
      // Fallback: pick the first plausible band containing 'DNB' or take first band
      targetBand = bands.find(b => /DNB|NTL|Radiance/i.test(b)) || bands[0];
    }

    // Helper: Build composite around a date with widening windows if needed
    async function compositeAround(dateStr) {
      const windows = [1, 3, 5, 7]; // +/- days
      for (const w of windows) {
        const start = ee.Date(dateStr).advance(-w, 'day');
        const end = ee.Date(dateStr).advance(w + 1, 'day');
        const col = ee.ImageCollection(datasetId)
          .filterBounds(geom)
          .filterDate(start, end)
          .select([targetBand]);
        const size = await col.size().getInfo();
        if (size === 0) {
          continue; // try wider window
        }
        const comp = col.median();
        // Mask non-positive and nulls to reduce noise
        const masked = comp.updateMask(comp.select(targetBand).gt(0));
        // Counts
        const totalCountDict = await ee.Image.constant(1).rename('c').reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: geom,
          scale: 1000,
          maxPixels: 1e9
        }).getInfo();
        const totalPx = totalCountDict ? totalCountDict['c'] : 0;

        const validCountDict = await masked.reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: geom,
          scale: 1000,
          maxPixels: 1e9
        }).getInfo();
        const validPx = validCountDict ? validCountDict[targetBand] : 0;

        if (!validPx || validPx === 0) {
          // Try wider window
          continue;
        }

        const meanDict = await masked.reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: geom,
          scale: 1000,
          maxPixels: 1e9
        }).getInfo();
        const meanVal = meanDict ? meanDict[targetBand] : null;

        if (meanVal === null || !isFinite(meanVal)) {
          // Calculation failure with this window; try a wider window
          continue;
        }

        return {
          image: masked,
          imagesCount: size,
          totalPx,
          validPx,
          mean: meanVal,
          windowDays: w
        };
      }
      // If we reach here, either no images or no valid pixels/mean in all windows
      return null;
    }

    const compA = await compositeAround(dateA);
    const compB = await compositeAround(dateB);

    // 3. Evaluate data presence and validity
    if (!compA || !compB) {
      // Determine specific reason for transparency
      const reasonA = compA ? '' : 'A';
      const reasonB = compB ? '' : 'B';
      // Check if no images at all near those dates
      async function windowHasImages(dateStr) {
        const col = ee.ImageCollection(datasetId)
          .filterBounds(geom)
          .filterDate(ee.Date(dateStr).advance(-15, 'day'), ee.Date(dateStr).advance(16, 'day'));
        return await col.size().getInfo();
      }
      const sizeA = await windowHasImages(dateA);
      const sizeB = await windowHasImages(dateB);
      if (reasonA && sizeA === 0 || reasonB && sizeB === 0) {
        console.log(`Empty near dates -> A:${sizeA} B:${sizeB}`);
        console.log('C1');
        return;
      }
      console.log('No valid pixels after masking and compositing for one/both dates.');
      console.log('C2');
      return;
    }

    // 4. Print concise evidence (<=20 lines)
    console.log(`Dataset: ${datasetId}, Band: ${targetBand}`);
    console.log(`Area total pixels (~1km): ${compA.totalPx}`);
    const validPctA = (compA.validPx / compA.totalPx) * 100.0;
    const validPctB = (compB.validPx / compB.totalPx) * 100.0;
    console.log(`2019-03-09: imgs=${compA.imagesCount}, window=±${compA.windowDays}d, valid_px=${compA.validPx} (${validPctA.toFixed(1)}%), mean=${compA.mean.toFixed(4)}`);
    console.log(`2019-03-24: imgs=${compB.imagesCount}, window=±${compB.windowDays}d, valid_px=${compB.validPx} (${validPctB.toFixed(1)}%), mean=${compB.mean.toFixed(4)}`);

    // 5. Validation & Final Answer
    if (!isFinite(compA.mean) || !isFinite(compB.mean)) {
      console.log('C3');
      return;
    }

    const delta = compB.mean - compA.mean;
    const pct = compA.mean !== 0 ? (delta / compA.mean) * 100.0 : 0;
    console.log(`Delta (24-09) = ${delta.toFixed(4)} (${pct.toFixed(1)}%)`);

    // Final decision: Was intensity lower on Mar 24 than Mar 9?
    if (compB.mean < compA.mean) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
